import{_ as a,a as o,c as n,ac as t}from"./chunks/framework.BSuaGltH.js";const g=JSON.parse('{"title":"MongoDB：模型、索引、原子性与一致性","description":"文档模型、索引、聚合、原子性与一致性。","frontmatter":{"title":"MongoDB：模型、索引、原子性与一致性","description":"文档模型、索引、聚合、原子性与一致性。","showdocs":{"topics":[{"id":"mongodb","title":"MongoDB","link":"/topics/mongodb/"}],"kind":"知识专题","scope":"general","audience":"general","group":"数据库与存储","seriesTitle":"MongoDB 文档模型与一致性理论","summary":"文档模型、索引、聚合、原子性与一致性。","status":"active","related":[{"title":"MongoDB 操作与命令","link":"/middleware/databases/mongodb/plus/ecosystem/mongodb-general-general","kind":"知识专题","scope":"general","audience":"general"},{"title":"MongoDB 数据库与认证操作","link":"/middleware/databases/mongodb/plus/subjects/mongodb-index","kind":"知识专题","scope":"general","audience":"general"},{"title":"MongoDB：版本化任务完整 CLI","link":"/middleware/databases/mongodb/plus/practice/application","kind":"应用实践","scope":"general","audience":"general"},{"title":"MongoDB 数据模型与配置","link":"/middleware/databases/mongodb/plus/subjects/mongodb-base-copy","kind":"知识专题","scope":"general","audience":"general"},{"title":"MongoDB：连接诊断、备份恢复与自检","link":"/middleware/databases/mongodb/operations","kind":"知识专题","scope":"general","audience":"general"}],"prev":{"text":"MongoDB：文档、命名空间与连接","link":"/middleware/databases/mongodb/base/basic/start"},"next":{"text":"MongoDB：版本化任务完整 CLI","link":"/middleware/databases/mongodb/plus/practice/application"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"MongoDB：文档、命名空间与连接","link":"/middleware/databases/mongodb/base/basic/start"},"next":{"text":"MongoDB：版本化任务完整 CLI","link":"/middleware/databases/mongodb/plus/practice/application"}},"headers":[],"relativePath":"middleware/databases/mongodb/base/intermediate/mechanisms.md","filePath":"middleware/databases/mongodb/base/intermediate/mechanisms.md"}'),r={name:"middleware/databases/mongodb/base/intermediate/mechanisms.md"};function d(i,e,s,c,l,m){return o(),n("div",null,[...e[0]||(e[0]=[t('<h1 id="mongodb-模型、索引、原子性与一致性" tabindex="-1">MongoDB：模型、索引、原子性与一致性 <a class="header-anchor" href="#mongodb-模型、索引、原子性与一致性" aria-label="Permalink to &quot;MongoDB：模型、索引、原子性与一致性&quot;">​</a></h1><p>前置是文档、集合、BSON 和过滤器。适用 MongoDB 8.0 版本族、PyMongo 4.x，核对 2026-10-17；下面的查询和事务均未执行。</p><h2 id="model" tabindex="-1">内嵌与引用的取舍 <a class="header-anchor" href="#model" aria-label="Permalink to &quot;内嵌与引用的取舍 {#model}&quot;">​</a></h2><p>MongoDB 内嵌模型把经常一起读写、有界增长的数据放进同一文档，引用模型把独立生命周期或高增长数据拆开。任务状态和版本适合放一起，无限评论列表通常要拆集合。灵活模式不是没有模式：应用需检查输入，集合验证器可限制字段类型和状态范围，已有坏数据还需迁移策略。<a href="https://www.mongodb.com/docs/manual/data-modeling/" target="_blank" rel="noopener noreferrer">官方数据建模</a></p><p>模型先问访问模式：需要按谁筛选、读多少项、如何更新以及规模如何增长。多表 JOIN 思维直接平移可能造成大量往返；反过来，把所有关联都内嵌也会造成大文档和写热点。无界增长的数组应考虑拆成独立集合并引用父文档标识，让分页、删除和容量控制有明确边界。本例只存任务当前状态，没有假装包含完整事件审计。</p><h2 id="indexes" tabindex="-1">联合索引与 explain <a class="header-anchor" href="#indexes" aria-label="Permalink to &quot;联合索引与 explain {#indexes}&quot;">​</a></h2><p>MongoDB 联合索引 owner,status,_id 主要服务以 owner 开头的过滤与对应排序。索引前缀影响可用方式，排序方向和等值/范围条件也影响是否需要额外排序。索引不是字段排列的任意集合，不能凭“都在索引里”就保证最优。explain 的 winningPlan、totalKeysExamined、totalDocsExamined 用来检查扫描成本；小样本计划不能代表生产。<a href="https://www.mongodb.com/docs/manual/core/indexes/index-types/index-compound/" target="_blank" rel="noopener noreferrer">官方联合索引</a></p><p>数组字段产生 multikey 索引，复合数组索引有额外限制；唯一索引还涉及缺失值、null 以及分片键边界。先检查已有重复数据，再建立唯一约束；不要把普通 createIndex 当作自动去重。示例 list 是全体任务按 _id 排序，主要依赖 _id 索引；owner_status_id 是供练习按 owner、status 查任务使用，不冒称它优化所有查询。</p><h2 id="aggregation" tabindex="-1">聚合管道与基数变化 <a class="header-anchor" href="#aggregation" aria-label="Permalink to &quot;聚合管道与基数变化 {#aggregation}&quot;">​</a></h2><p>MongoDB 聚合管道把数据依次交给 <code>$match</code>、<code>$group</code>、<code>$sort</code>、<code>$project</code> 等阶段。<code>$group</code> 按状态汇总任务数，结果顺序需要额外 <code>$sort</code>；<code>$unwind</code> 会把数组展开成多行，因此计数之前必须明确统计的是任务还是元素。尽早可下推的过滤常能减少后续输入，但优化器行为仍要用 explain 检查。<a href="https://www.mongodb.com/docs/manual/aggregation/" target="_blank" rel="noopener noreferrer">官方聚合</a></p><p><code>$group: {_id:&quot;$status&quot;,count:{$sum:1}}</code> 按文档计数，字段缺失可能与预期状态域不一致。聚合不保证所有阶段都由索引完成，也不意味着计算结果自动持久化。练习：一个任务有三个标签，unwind 后 count 是几？解答：三条展开结果，若要任务数需先按任务去重或不要展开。</p><h2 id="atomic" tabindex="-1">单文档原子更新与版本条件 <a class="header-anchor" href="#atomic" aria-label="Permalink to &quot;单文档原子更新与版本条件 {#atomic}&quot;">​</a></h2><p>MongoDB 单文档原子性保证同一文档的一次更新不会对外暴露半套字段。把 _id、version、status 放进 find_one_and_update 过滤器，匹配时同时 <code>$set</code> 状态并 <code>$inc</code> 版本，就能检测过期提交；只按 _id 更新则可能让后写覆盖先写。未匹配并不自动说明数据库故障，它也可能是版本过期或任务已完成。<a href="https://www.mongodb.com/docs/manual/core/write-operations-atomicity/" target="_blank" rel="noopener noreferrer">官方原子性</a></p><p>updateMany 对每个文档的更新原子，不代表整批多文档一起原子。本示例每次操作只需一份任务文档，不需要多文档事务；这来自业务模型，不能推广成 MongoDB 永远无需事务。</p><h2 id="transactions" tabindex="-1">事务拓扑与重试边界 <a class="header-anchor" href="#transactions" aria-label="Permalink to &quot;事务拓扑与重试边界 {#transactions}&quot;">​</a></h2><p>MongoDB 多文档事务要求副本集或分片集群，独立 standalone 不能作为等价事务环境。副本集复制同一数据集，分片则按分片键分布数据，两者解决的问题不同。使用会话和 with_transaction 时回调可能重试，回调里的邮件或支付等外部副作用必须另行安排幂等和提交后处理。<a href="https://www.mongodb.com/docs/manual/core/transactions/" target="_blank" rel="noopener noreferrer">官方事务</a></p><p>跨集合库存与订单若必须同时成立，可以在合适拓扑中使用事务并保持操作短小；不能用两次独立更新冒充原子提交。驱动的瞬态事务重试和提交结果不确定处理有不同目的，业务仍需一个可查询的请求身份。事务隔离、读关注和提交写关注要一起设计，而不是只加 start_transaction。</p><h2 id="consistency" tabindex="-1">读写关注与因果一致性 <a class="header-anchor" href="#consistency" aria-label="Permalink to &quot;读写关注与因果一致性 {#consistency}&quot;">​</a></h2><p>MongoDB majority 写关注表示按拓扑要求获得多数确认，majority 读关注选择多数提交的数据；readPreference 决定把读发到哪里，它与 readConcern 不是一回事。副本延迟意味着从 secondary 读取可能旧于刚完成的写入，不能把 majority 简化成所有节点立即同步。<a href="https://www.mongodb.com/docs/manual/core/read-isolation-consistency-recency/" target="_blank" rel="noopener noreferrer">官方一致性</a></p><p>需要会话内因果顺序时，应按官方条件使用因果一致会话及 majority 读写关注。线性化读取又有独立适用条件和性能代价。本例独立 CLI 进程间没有共享因果会话，所以 list 仅提供当前查询，不承诺跨进程“读己之写”的一般证明。wtimeout 可能表示确认超时，不能据此断言写入一定没发生；重试前应查业务身份。</p>',20)])])}const b=a(r,[["render",d]]);export{g as __pageData,b as default};
